arguments.command:
python3 -c "
import zipfile
with zipfile.ZipFile('/root/training_feedback_ready.hwpx', 'r') as z:
    content0 = z.read('Contents/section0.xml').decode('utf-8')
    content1 = z.read('Contents/section1.xml').decode('utf-8')

    # Check section0 - headers should have linesegarray, data paragraphs should NOT
    print('section0.xml checks:')
    if '교육 피드백 시트' in content0 and '<hp:linesegarray>' in content0.split('교육 피드백 시트')[0] + '교육 피드백 시트':
        print('  Header has linesegarray (expected)')

    # Check if data paragraphs don't have linesegarray
    import re
    paras = re.findall(r'<hp:p[^>]*>(.*?)</hp:p>', content0, re.DOTALL)
    for para in paras:
        if '교육명:' in para and 'linesegarray' not in para:
            print('  ✓ 교육명 paragraph: linesegarray removed')
        if '참석자 수:' in para and 'linesegarray' not in para:
            print('  ✓ 참석자수 paragraph: linesegarray removed')
        if '만족도:' in para and 'linesegarray' not in para:
            print('  ✓ 만족도 paragraph: linesegarray removed')

    print()
    print('section1.xml checks:')
    paras1 = re.findall(r'<hp:p[^>]*>(.*?)</hp:p>', content1, re.DOTALL)
    for para in paras1:
        if '강사 전문성:' in para and 'linesegarray' not in para:
            print('  ✓ 강사평가 paragraph: linesegarray removed')
        if '종합 의견:' in para and 'linesegarray' not in para:
            print('  ✓ 종합의견 paragraph: linesegarray removed')
        if '세부 평가' in para and 'linesegarray' in para:
            print('  Header has linesegarray (expected)')
"

